package dev.gbppimentel.snapcompanion;
import android.content.Context;import java.nio.*;import java.util.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=33)
public class CourseResearchTest {
 private Context c;private EdenLinkStore link;private CourseResearch research;private final String user="A".repeat(32),hash="b".repeat(64);
 @Before public void setup()throws Exception{c=RuntimeEnvironment.getApplication();for(String p:List.of("snap","snap-eden","snap-course-research"))c.getSharedPreferences(p,0).edit().clear().commit();link=new EdenLinkStore(c);link.publish("default",user,hash,new EdenPhotodex.Snapshot(Map.of(),0,0));research=new CourseResearch(c);}
 private EdenResearch.Snapshot saved(int gross,int offset)throws Exception{byte[] data=new byte[15464],flags=new byte[2960];flags[0]=2;ByteBuffer b=ByteBuffer.wrap(data).order(ByteOrder.LITTLE_ENDIAN);b.putShort(8,(short)1);for(int star=0;star<4;star++){int n=Math.min(gross,65535);gross-=n;b.putShort(12+2*star,(short)n);}for(int i=0;i<3;i++)data[497+i]=(byte)(offset>>(8*i));return new EdenResearch.Snapshot(EdenResearch.decode(data,flags,GuideBookTest.asset("guidebook.json")),1000,user,hash);}
 @Test public void savedPointsUseTheGameOffsetAndPublishNextResearchTarget()throws Exception{research.publish("default",saved(115000,10000));var r=research.snapshot("default").getJSONObject("park-day");assertEquals(105000,r.getInt("points"));assertEquals(2,r.getInt("level"));assertEquals(110000,r.getInt("next"));assertEquals(3,r.getInt("nextLevel"));assertEquals(40000,r.getInt("base"));assertFalse(research.snapshot("default").has("park-night"));}
 @Test public void saveRevisionAndProfileChangesHideOldDataWithoutDeletingIt()throws Exception{research.publish("default",saved(115000,10000));link.publish("default",user,"c".repeat(64),new EdenPhotodex.Snapshot(Map.of(),0,0));assertEquals(0,research.snapshot("default").length());assertTrue(c.getSharedPreferences("snap-course-research",0).contains("default"));assertEquals(0,research.snapshot("other").length());}
 @Test public void stalePublicationCannotReplaceTheCurrentSave()throws Exception{var original=saved(115000,10000);link.publish("default",user,"c".repeat(64),new EdenPhotodex.Snapshot(Map.of(),0,0));research.publish("default",original);assertFalse(c.getSharedPreferences("snap-course-research",0).contains("default"));}
 @Test public void malformedCachedResearchIsNotDisplayed()throws Exception{research.publish("default",saved(115000,10000));JSONObject row=new JSONObject(c.getSharedPreferences("snap-course-research",0).getString("default",""));row.getJSONObject("courses").getJSONObject("park-day").put("offset",-1);c.getSharedPreferences("snap-course-research",0).edit().putString("default",row.toString()).commit();assertEquals(0,research.snapshot("default").length());}
 @Test public void savedResearchNeverSetsLiveCourseOrRewritesManualRecords()throws Exception{String manual="unchanged private notebook";c.getSharedPreferences("snap",0).edit().putString("progress",manual).commit();research.publish("default",saved(115000,10000));try(var activity=Robolectric.buildActivity(MainActivity.class).setup()){var state=activity.get().snapshot();assertTrue(state.getJSONObject("researchCourses").has("park-day"));assertEquals("",state.getString("course"));assertEquals(0,state.getInt("level"));}assertEquals(manual,c.getSharedPreferences("snap",0).getString("progress",""));}
 @Test public void forestSeasonsAreSourceBoundAndDoNotInventResearchOrPhotoForms()throws Exception{byte[] data=new byte[15464],flags=new byte[2960];ByteBuffer.wrap(data).order(ByteOrder.LITTLE_ENDIAN).putShort(9*504+488,(short)72);research.publish("default",new EdenResearch.Snapshot(EdenResearch.decode(data,flags,GuideBookTest.asset("guidebook.json")),1000,user,hash));var forest=research.snapshot("default").getJSONObject("forest");assertTrue(forest.getBoolean("seasonsKnown"));assertEquals("[0,3]",forest.getJSONArray("seasons").toString());assertFalse(forest.has("points"));assertTrue(link.photos("default").isEmpty());link.publish("default",user,"c".repeat(64),new EdenPhotodex.Snapshot(Map.of(),0,0));assertEquals(0,research.snapshot("default").length());}
 @Test public void oldResearchCacheDoesNotClaimSeasonDiscoveries()throws Exception{JSONObject courses=new JSONObject().put("forest",new JSONObject().put("gross",5000).put("offset",0));JSONObject row=new JSONObject().put("schema",1).put("user",user).put("hash",hash).put("at",1000).put("courses",courses);c.getSharedPreferences("snap-course-research",0).edit().putString("default",row.toString()).commit();var forest=research.snapshot("default").getJSONObject("forest");assertEquals(5000,forest.getInt("points"));assertFalse(forest.has("seasonsKnown"));}
}
